/**
 * The SDK's file tools normalize every path to POSIX form with a leading
 * `/`, so a Windows path such as `C:\Users\me\a.txt` reaches a FileSystem
 * as `/C:/Users/me/a.txt`. Strip that leading `/` on Windows so the host
 * path module sees a drive path.
 */
export function hostPathFromToolPath(input, platform = process.platform) {
    if (platform === "win32" && /^\/[A-Za-z]:(?:[\\/]|$)/.test(input)) {
        return input.slice(1);
    }
    return input;
}
